/* ==================== 模块01：资源与授权 ==================== */
/* ---------- 字体资源 ---------- */
/* 正文使用 Clear Han Serif，界面图标使用 Lucide。 */
@import url("https://fontsapi.zeoseven.com/79/main/result.css");
/* Lucide图标字体资源。新增图标的写法见图标模块。 */
@font-face {
  font-family: "Notion Lucide";
  src: url("https://unpkg.com/lucide-static@0.468.0/font/lucide.woff2") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: block;
}

/* ==================== 模块02：用户定制 ==================== */
/* ---------- 使用说明 ----------
 修改冒号后的值，保留分号。px 是像素；em 会随字号缩放。
 在酒馆的自定义 CSS 中修改后，保存为当前主题即可。
 下方按字体、尺寸、颜色、文字、图片和可选功能分组。
*/
:root {
  /* ---------- 字体与排版：正文 ---------- */
  /* 字体名称；更换网络字体时同步修改文件开头的 @import 地址。 */
  --nt-serif: "Clear Han Serif", "Songti SC", STSong, SimSun, serif;
  /* 代码字体。 */
  --nt-mono: Consolas, "Liberation Mono", monospace;
  /* 正文大小：随酒馆字号缩放，此系数默认约为 16px。 */
  --nt-body: calc(var(--mainFontSize) * 1.066667);
  /* 正文行高：1.8 表示字号的 1.8 倍；1.6 更紧凑，2 更宽松。 */
  --nt-body-line-height:1.8;
  /* 正文段后空隙：.75em 为约四分之三个字号；调大使段落更疏朗。 */
  --nt-body-paragraph-gap:.75em;
  /* 推理文字的行高、段后空隙，可与正文分别调整。 */
  --nt-reasoning-line-height:1.8;
  --nt-reasoning-paragraph-gap:.75em;
  /* ---------- 字体与排版：界面字号 ---------- */
  /* 以下字号均随酒馆字号设置缩放。 */
  --nt-ui: calc(var(--mainFontSize) * .933333);
  --nt-note: calc(var(--mainFontSize) * .866667);
  --nt-title: calc(var(--mainFontSize) * 1.2);

  /* ---------- 页面与尺寸 ---------- */
  /* 纸面、正文和输入区可分别调节宽度。 */
  --nt-page-max:920px;
  --nt-reading:820px;
  --nt-input-max:820px;
  /* 手机正文左右留白，首楼和普通楼层共用。 */
  --nt-mobile-inset:14px;
  /* 通用控件圆角；数字越大越圆。 */
  --nt-radius:4px;
  /* 大头像直径：电脑、手机。 */
  --nt-cover-avatar-desktop:80px;
  --nt-cover-avatar-mobile:64px;
  /* TopInfoBar 聊天侧栏宽度；手机自动限制在屏幕范围内。 */
  --nt-sidebar-width:320px;
  /* 细滚动条宽度，轨道透明。 */
  --nt-scrollbar-size:6px;

  /* ---------- 颜色：浅色代码与危险操作 ---------- */
  --moon-light-nt-code:#934F45;
  --moon-light-nt-keyword:#805064;
  --moon-light-nt-string:#865B48;
  --moon-light-nt-danger:#a13e38;
  /* ---------- 颜色：文字层级与交互强度 ---------- */
  /* 推理文字由 85% 正文色与 15% 次级色混合；降低前者会更淡。 */
  --nt-reasoning-text:color-mix(in srgb,var(--nt-text) 85%,var(--nt-muted));
  /* 未启用预设的名称与说明颜色。 */
  --nt-preset-inactive-text:var(--nt-muted);
  /* 输入字段、卡片混入正文色的比例；调大使底色对比更明显。 */
  --nt-field-tone:6%;
  --nt-card-tone:1.5%;
  /* 快捷按钮鼠标悬停、按下时的底色强度。 */
  --nt-quick-hover-tone:8%;
  --nt-quick-active-tone:12%;
  /* 选中文字的蓝色强度：浅色、深色。 */
  --nt-selection-light-tone:24%;
  --nt-selection-dark-tone:28%;

}
/* ---------- 颜色：浅色模式 ---------- */
:root {
  /* 成功状态 */
  --moon-light-nt-success: #447544;
  /* 提醒状态 */
  --moon-light-nt-warning: #886019;
  /* 人设选中边框 */
  --moon-light-nt-selection: #587F96;
  /* 正文文字 */
  --moon-light-BodyColor: #37352F;
  /* 次级文字与斜体 */
  --moon-light-EmColor: #686762;
  /* 链接与焦点 */
  --moon-light-QuoteColor: #526C78;
  /* 下划线与标题短线 */
  --moon-light-UnderlineColor: #87585E;
  /* 面板、菜单与导航表面 */
  --moon-light-BlurTintColor: #F4F2ED;
  /* 聊天纸面 */
  --moon-light-ChatTintColor: #FAF9F6;
  /* 用户楼层底色，transparent 为透明 */
  --moon-light-UserMesBlurTintColor: transparent;
  /* 角色楼层底色，transparent 为透明 */
  --moon-light-BotMesBlurTintColor: transparent;
  /* 边框与分割线 */
  --moon-light-BorderColor: #E4E0D8;
  /* 浮层阴影 */
  --moon-light-ShadowColor:rgba(35,35,30,.09);
  /* 快速界面背景 */
  --moon-light-FastUIBGColor:#F4F2ED;
  /* 复选框底色的红、绿、蓝通道及不透明度 */
  --moon-light-CheckboxBgColorR:55;
  --moon-light-CheckboxBgColorG:53;
  --moon-light-CheckboxBgColorB:47;
  --moon-light-CheckboxBgColorA:1;
  /* 复选框勾选颜色 */
  --moon-light-CheckboxTickColor:#ffffff;
}
/* ---------- 颜色：深色模式 ---------- */
:root {
  /* 人设选中边框 */
  --moon-dark-nt-selection: #79A0B7;
  /* 正文文字 */
  --moon-dark-BodyColor: #e6e4df;
  /* 次级文字与斜体 */
  --moon-dark-EmColor: #b2afa8;
  /* 链接与焦点 */
  --moon-dark-QuoteColor: #A5B7BF;
  /* 下划线与标题短线 */
  --moon-dark-UnderlineColor: #D0A1A8;
  /* 面板、菜单与导航表面 */
  --moon-dark-BlurTintColor: #202020;
  /* 聊天纸面 */
  --moon-dark-ChatTintColor: #191919;
  /* 用户楼层底色，transparent 为透明 */
  --moon-dark-UserMesBlurTintColor: transparent;
  /* 角色楼层底色，transparent 为透明 */
  --moon-dark-BotMesBlurTintColor: transparent;
  /* 边框与分割线 */
  --moon-dark-BorderColor: #41413e;
  /* 浮层阴影 */
  --moon-dark-ShadowColor: #00000040;
  /* 快速界面背景 */
  --moon-dark-FastUIBGColor: #202020;
  /* 复选框红通道（0—255） */
  --moon-dark-CheckboxBgColorR: 230;
  /* 复选框绿通道（0—255） */
  --moon-dark-CheckboxBgColorG: 228;
  /* 复选框蓝通道（0—255） */
  --moon-dark-CheckboxBgColorB: 223;
  /* 复选框不透明度（0—1） */
  --moon-dark-CheckboxBgColorA: 1;
  /* 复选框勾选颜色 */
  --moon-dark-CheckboxTickColor: #191919;
  /* 行内代码 */
  --moon-dark-nt-code: #DCA397;
  /* 代码关键字 */
  --moon-dark-nt-keyword: #CDA2B7;
  /* 代码字符串 */
  --moon-dark-nt-string: #D3B09B;
  /* 危险操作 */
  --moon-dark-nt-danger: #eb9a94;
  /* 成功状态 */
  --moon-dark-nt-success: #a2c89d;
  /* 提醒状态 */
  --moon-dark-nt-warning: #e1be78;
}

:root {
  /* ---------- 文字内容 ---------- */
  /* 保留英文双引号；\A 表示换行，空字符串 "" 留空。 */
  --nt-hint:"☾ 月色会记得，我们在此相遇 ☽";
  --nt-reasoning-label:"☾ 月相记录 ☽";
  --nt-epigraph:"“直到月亮\A来慰藉这不安的世界，用它的冷冷晖光”";
  --nt-loading-label:"月出中";

  /* ---------- 图片 ---------- */
  /* 替换url中的地址，使用图床图片直链。 */
  /* 页面背景：浅色、深色；随下方显示模式切换。 */
  --nt-background-light:url("https://cloudflare-imgbed-dm8.pages.dev/file/1788635093790_月相风格背景图.png");
  --nt-background-dark:url("https://cloudflare-imgbed-dm8.pages.dev/file/1788665450111_月相风格背景图-深色.png");
  /* 用户自选背景在深色模式的蒙版：0 为原图，1 为全黑。 */
  --nt-dark-background-shade:.22;
  /* 头图：默认按宽高比 8:3 展示；顶部衔接色填写接近图片上边缘的颜色。 */
  --nt-cover-light:url("https://cloudflare-imgbed-dm8.pages.dev/file/1788630967299_月相风格头图.png");
  --nt-cover-edge-light:#c8c6be;
  /* 深色模式默认使用同一张头图和同一衔接色。 */
  --nt-cover-dark:var(--nt-cover-light);
  --nt-cover-edge-dark:var(--nt-cover-edge-light);
  /* 深色头图示例：删除下一块代码前后的注释符号即可启用。 */
  /*
  --nt-cover-dark:url("https://cloudflare-imgbed-dm8.pages.dev/file/1788665657734_月相风格头图-深色.png");
  --nt-cover-edge-dark:#191918;
  */
}
/* ---------- 可选功能：自定义页宽（V1.1.1模式） ----------
 删除下一块代码外侧的注释符号后，页面和正文跟随酒馆页宽滑块。
 例如 1440px 屏幕设为 64，纸面约 922px；设为 100 可铺满。
 输入区仍使用上方 --nt-input-max 的值。
*/
/*
:root { --nt-page-max:100vw; --nt-reading:100%; }
*/

/* ---------- 可选功能：聊天滚动条 ----------
 下方两条规则默认隐藏聊天滚动条。将两条一起包进注释即可恢复细条。
 滚轮、触摸和键盘均可正常滚动；菜单和代码块使用前面的细条宽度。
*/
#chat { scrollbar-width:none; scrollbar-gutter:auto; }
#chat::-webkit-scrollbar { display:none; width:0; height:0; }

