  --SmartThemeUnderlineColor:var(--moon-light-UnderlineColor)!important;
  --SmartThemeBlurTintColor:var(--moon-light-BlurTintColor)!important;
  --SmartThemeChatTintColor:var(--moon-light-ChatTintColor)!important;
  --SmartThemeUserMesBlurTintColor:var(--moon-light-UserMesBlurTintColor)!important;
  --SmartThemeBotMesBlurTintColor:var(--moon-light-BotMesBlurTintColor)!important;
  --SmartThemeBorderColor:var(--moon-light-BorderColor)!important;
  --SmartThemeShadowColor:var(--moon-light-ShadowColor)!important;
  --SmartThemeFastUIBGColor:var(--moon-light-FastUIBGColor)!important;
