  --SmartThemeCheckboxBgColorA:var(--moon-light-CheckboxBgColorA)!important;
  --SmartThemeCheckboxTickColor:var(--moon-light-CheckboxTickColor)!important;
  --nt-code:var(--moon-light-nt-code);
  --nt-keyword:var(--moon-light-nt-keyword);
  --nt-string:var(--moon-light-nt-string);
  --nt-danger:var(--moon-light-nt-danger);
  --nt-success:var(--moon-light-nt-success);
  --nt-warning:var(--moon-light-nt-warning);
  --nt-selection:var(--moon-light-nt-selection);
