/* ==================== 模块03：主题基础 ==================== */
/* ---------- 语义变量 ---------- */
/* 语义变量从原生配色读取，具体颜色在用户配置区修改。 */
:root {
  --nt-text: var(--SmartThemeBodyColor);
  --nt-muted: var(--SmartThemeEmColor);
  --nt-accent: var(--SmartThemeQuoteColor);
  --nt-accent-alt: var(--SmartThemeUnderlineColor);
  --nt-surface: var(--SmartThemeBlurTintColor);
  --nt-paper: var(--SmartThemeChatTintColor);
  --nt-border: var(--SmartThemeBorderColor);
  --nt-field-surface:color-mix(in srgb,var(--nt-text) var(--nt-field-tone),var(--nt-surface));
  --nt-card-surface:color-mix(in srgb,var(--nt-text) var(--nt-card-tone),var(--nt-surface));
  --nt-quick-hover:color-mix(in srgb,var(--nt-text) var(--nt-quick-hover-tone),var(--nt-surface));
  --nt-quick-active:color-mix(in srgb,var(--nt-text) var(--nt-quick-active-tone),var(--nt-surface));
  --nt-selection-bg:color-mix(in srgb,var(--nt-selection) var(--nt-selection-light-tone),var(--nt-paper));
  --nt-secondary: color-mix(in srgb, var(--nt-surface) 95%, var(--nt-text));
  --nt-hover: color-mix(in srgb, var(--nt-surface) 90%, var(--nt-text));
  --nt-active: color-mix(in srgb, var(--nt-surface) 84%, var(--nt-text));
  --nt-float-shadow: 0 5px 20px var(--SmartThemeShadowColor);

  --nt-metadata:calc(var(--mainFontSize) * .8);

  --nt-danger-bg: color-mix(in srgb, var(--nt-surface) 92%, var(--nt-danger));

  --nt-tool:32px;
  --nt-control:var(--nt-tool); /* 兼容名称：仅用于工具按钮 */
  --nt-field:32px;
  --nt-menu:36px;
  --nt-chip:24px;
  --nt-tool-gap:2px;
  --nt-field-gap:4px;
  --nt-check-gap:6px;
  --nt-group-gap:8px;
  --nt-region-gap:12px;
  --nt-icon:16px;

  --mainFontFamily: var(--nt-serif);
  --monoFontFamily: var(--nt-mono);
}
@media (pointer:coarse), (max-width:600px) { :root { --nt-field:36px; } }

/* ---------- 主题接口 ---------- */
:root {
  --st-theme-accent: var(--nt-accent);
