  --st-theme-bot-message: var(--SmartThemeBotMesBlurTintColor);
  --st-theme-border: var(--nt-border);
  --st-theme-shadow: var(--SmartThemeShadowColor);
  --st-theme-radius-sm: 4px;
  --st-theme-radius-md: 6px;
  --st-theme-radius-lg: 8px;
  --st-theme-space-1: 4px;
  --st-theme-space-2: 8px;
  --st-theme-space-3: 14px;
  --st-theme-space-4: 20px;
  --st-theme-transition: 120ms ease;
}

