body { background-color:var(--nt-paper); background-image:var(--nt-default-background); background-size:cover; background-position:center; background-attachment:fixed; }
#bg1 { background-color:transparent; }
#bg1::after { content:""; position:absolute; inset:0; pointer-events:none; background:rgb(0 0 0 / var(--nt-user-background-shade)); }
