/* ---------- 初始化界面 ---------- */
/* 初始化界面使用全屏背景、居中文字与圆点动画。 */
/* 初始化弹窗使用完整视口。 */
dialog.popup:has(#loader.splash-screen) { position:fixed; inset:0; box-sizing:border-box; width:100dvw; min-width:0; max-width:100dvw!important; height:100dvh!important; min-height:0; max-height:100dvh; margin:0; padding:0; border:0; border-radius:0; box-shadow:none; background:var(--nt-paper) var(--nt-default-background) center / cover no-repeat; backdrop-filter:none; }
dialog.popup:has(#loader.splash-screen)::backdrop { background:var(--nt-paper); backdrop-filter:none; }
dialog.popup:has(#loader.splash-screen) :is(.popup-body,.popup-content) { height:100%; padding:0; background:transparent; box-shadow:none; }
/* 文字安全区与居中排版。 */
dialog.popup #loader.splash-screen { position:absolute; inset:0; width:auto; height:auto; padding-block:max(24px,env(safe-area-inset-top,0px),env(safe-area-inset-bottom,0px)); padding-inline:max(24px,env(safe-area-inset-left,0px),env(safe-area-inset-right,0px)); gap:16px; box-sizing:border-box; color:var(--nt-text); }
#loader.splash-screen .splash-logo { display:none; }
dialog.popup #loader.splash-screen #load-spinner { position:static; width:max-content; min-width:max-content; height:auto; display:flex; flex:none; justify-content:center; align-items:baseline; gap:0; white-space:nowrap; font-family:var(--nt-serif); font-size:var(--nt-title); font-weight:400; line-height:1.8; color:var(--nt-text); text-shadow:none; transition:none; animation:none; transform:none; }
/* 加载文字和圆点动画。 */
#loader.splash-screen #load-spinner::before { content:var(--nt-loading-label); flex:none; white-space:nowrap; font-family:var(--nt-serif)!important; font-size:inherit; line-height:inherit; }
#loader.splash-screen #load-spinner::after { content:"..."; display:inline-block; width:3ch; font-family:var(--nt-mono); clip-path:inset(0 66.666% 0 0); animation:nt-moonrise-dots 1.5s steps(1,end) infinite; }
/* 初始化状态文案。 */
#loader.splash-screen .splash-message[data-i18n="Initializing…"] { display:none; }
#loader.splash-screen .splash-message { font-family:var(--nt-serif); color:var(--nt-text); text-align:center; max-width:100%; overflow-wrap:anywhere; }
@keyframes nt-moonrise-dots { 0%,100% { clip-path:inset(0 66.666% 0 0); } 33.333% { clip-path:inset(0 33.333% 0 0); } 66.666% { clip-path:inset(0); } }
body.reduced-motion #loader.splash-screen #load-spinner::after { animation:none; clip-path:none; }
@media(prefers-reduced-motion:reduce) { #loader.splash-screen #load-spinner::after { animation:none; clip-path:none; } }

