.select2-container.select2-container--default .select2-selection__clear { position:absolute; top:0; right:0; display:flex; align-items:center; justify-content:center; float:none; width:var(--nt-field); min-width:var(--nt-field); height:var(--nt-field); min-height:0; margin:0; padding:0; border:0; border-radius:4px; background:transparent; color:var(--nt-muted); font:400 20px/1 sans-serif; text-shadow:none; box-shadow:none; }
