.select2-dropdown { box-sizing:border-box; background:var(--nt-surface); color:var(--nt-text); border:1px solid var(--nt-border); border-radius:6px; box-shadow:var(--nt-float-shadow); overflow:hidden; font-family:var(--nt-serif); }
