/* ---------- 滑块、滚动条与通知 ---------- */
/* 参数滑块使用2px轨道与完整点击区域。 */
input[type=range],.drawer-content input.neo-range-slider { appearance:none; height:var(--nt-control)!important; background:transparent!important; border:0; border-radius:0!important; padding:0; box-shadow:none!important; filter:none; }
