input[type=range]::-webkit-slider-thumb { appearance:none; width:10px; height:10px; margin-top:-4px; border:1px solid var(--nt-muted); border-radius:50%; background:var(--nt-muted); box-shadow:none; }
input[type=range]::-moz-range-thumb { width:10px; height:10px; border:0; border-radius:50%; background:var(--nt-muted); box-shadow:none; }
