.drawer-content .neo-range-input { color:var(--nt-text); background:var(--nt-surface); border:1px solid var(--nt-border); border-radius:4px; font-size:var(--nt-ui); }
@media(pointer:coarse) { input[type=range]::-webkit-slider-thumb { width:14px; height:14px; margin-top:-6px; } input[type=range]::-moz-range-thumb { width:14px; height:14px; } body .ui-slider .ui-slider-handle { width:14px; height:14px; top:-6px; } }
/* 页面细滚动条：透明轨道与主题色滑块。 */
:where(html,body,body *) { scrollbar-color:var(--nt-muted) transparent; }
@supports not selector(::-webkit-scrollbar) {
 :where(html,body,body *) { scrollbar-width:thin; }
}
@supports selector(::-webkit-scrollbar) {
 /* 支持伪元素的浏览器使用像素宽度。 */
