 ::-webkit-scrollbar { width:var(--nt-scrollbar-size); height:var(--nt-scrollbar-size); }
 :is(#extensionsMenu,#options,.drawer-content,.popup,.list-group,.options-content,.select2-results__options)::-webkit-scrollbar { width:var(--nt-scrollbar-size); height:var(--nt-scrollbar-size); }
 body ::-webkit-scrollbar,body ::-webkit-scrollbar-track,body ::-webkit-scrollbar-track:hover,body ::-webkit-scrollbar-track-piece,body ::-webkit-scrollbar-corner { background:transparent; border:0; box-shadow:none; }
 html::-webkit-scrollbar,html::-webkit-scrollbar-track,html::-webkit-scrollbar-corner { background:transparent; border:0; box-shadow:none; }
 html::-webkit-scrollbar-thumb:vertical,html::-webkit-scrollbar-thumb:horizontal,body ::-webkit-scrollbar-thumb:vertical,body ::-webkit-scrollbar-thumb:horizontal,body.movingUI ::-webkit-scrollbar-thumb:vertical { background:var(--nt-muted); background-clip:border-box; border:0; border-radius:3px; box-shadow:none; }
 body ::-webkit-scrollbar-thumb:hover { background:var(--nt-text); }
}
/* 通知：主题表面与单个状态图标。 */
body #toast-container > .toast { --nt-status:var(--nt-accent); position:relative; background-image:none!important; background-color:var(--nt-surface); background-repeat:no-repeat; color:var(--nt-text); opacity:1; filter:none; text-shadow:none; border:1px solid var(--nt-border); border-left:3px solid var(--nt-status); border-radius:8px; box-shadow:var(--nt-float-shadow); font:400 var(--nt-ui)/1.5 var(--nt-serif); padding:12px 40px 12px 42px; width:min(360px,calc(100vw - 24px)); }
