body #toast-container .toast-close-button { position:absolute; inset:8px 8px auto auto; float:none; width:24px; height:24px; padding:0; color:var(--nt-muted); text-shadow:none; filter:none; opacity:1; line-height:24px; font:400 20px/24px var(--nt-serif); border-radius:4px; }
