/* ---------- 富文本 ---------- */
/* 统一正文、推理、标题、引用与代码。 */
#chat :is(.mes_text,.mes_reasoning) { overflow-wrap:anywhere; text-shadow:none; }
#chat .mes_text { color:var(--nt-text); }
#chat .mes_reasoning { color:var(--nt-reasoning-text); }
#chat .mes_text { font:400 var(--nt-body)/var(--nt-body-line-height) var(--nt-serif); padding:0; }
#chat .mes_reasoning { font:400 var(--nt-ui)/var(--nt-reasoning-line-height) var(--nt-serif); padding:8px 12px; border-left:1px solid var(--nt-border); background:transparent; }
#chat .mes_text p { margin:0 0 var(--nt-body-paragraph-gap); }
#chat .mes_reasoning p { margin:0 0 var(--nt-reasoning-paragraph-gap); }
#chat :is(.mes_text,.mes_reasoning) :is(h1,h2,h3) { color:var(--nt-text); font-family:var(--nt-serif); line-height:1.4; margin:1.2em 0 .6em; }
#chat :is(.mes_text,.mes_reasoning) h1 { font-size:calc(var(--mainFontSize) * 1.866667); line-height:1.4; margin:1.4em 0 .8em; font-weight:600; }
#chat :is(.mes_text,.mes_reasoning) h1 { text-decoration:underline; text-decoration-color:var(--nt-accent-alt); text-decoration-thickness:2px; text-underline-offset:10px; text-decoration-skip-ink:none; }
#chat :is(.mes_text,.mes_reasoning) h1 :is(a,code) { text-decoration:none; }
@media(max-width:600px) { #chat :is(.mes_text,.mes_reasoning) h1 { font-size:calc(var(--mainFontSize) * 1.6); } }
#chat :is(.mes_text,.mes_reasoning) u { color:var(--nt-accent-alt); text-decoration-color:currentColor; text-underline-offset:.2em; }
#chat :is(.mes_text,.mes_reasoning) a { color:var(--nt-accent); } #chat .mes_text h2 { font-size:1.5em; } #chat .mes_text h3 { font-size:1.25em; }
#chat :is(.mes_text,.mes_reasoning) blockquote { border-left:2px solid var(--nt-muted); padding-left:14px; background:transparent; margin:12px 0; }
#chat :is(.mes_text,.mes_reasoning) code { font-family:var(--nt-mono); color:var(--nt-code); background:var(--nt-secondary); border:0; text-shadow:none; }
#chat :is(.mes_text,.mes_reasoning) pre { padding:12px; background:var(--nt-secondary); border:0; border-radius:4px; max-width:100%; overflow:auto; }
#chat :is(.mes_text,.mes_reasoning) pre code,#chat :is(.mes_text,.mes_reasoning) pre code [class] { color:var(--nt-text); background:transparent; text-shadow:none; }
#chat :is(.mes_text,.mes_reasoning) pre code :is(.hljs-comment,.hljs-quote) { color:var(--nt-muted); }
#chat :is(.mes_text,.mes_reasoning) pre code :is(.hljs-keyword,.hljs-selector-tag) { color:var(--nt-keyword); }
#chat :is(.mes_text,.mes_reasoning) pre code :is(.hljs-string,.hljs-attr) { color:var(--nt-string); }
#chat :is(.mes_text,.mes_reasoning) table { display:block; max-width:100%; overflow-x:auto; border-collapse:collapse; }
#chat :is(.mes_text,.mes_reasoning) :is(td,th) { padding:8px 10px; border:1px solid var(--nt-border); }
#chat :is(.mes_text,.mes_reasoning) th { background:var(--nt-secondary); }
#chat .mes_text :is(img,video,audio) { max-width:100%; border-radius:4px; }
#chat .mes_text img { height:auto; object-fit:contain; }
/* 推理标题行与展开内容布局。 */
#chat .mes_reasoning_details { margin-inline:0; }
#chat .mes_reasoning_details .mes_reasoning_summary { display:flex; align-items:flex-start; flex-wrap:wrap; min-height:var(--nt-control); margin:0; padding:0; gap:4px; }
#chat .mes_reasoning_summary > span { margin:0; }
#chat .mes_reasoning_header_block { display:flex; align-items:center; min-height:var(--nt-control); }
#chat .mes_reasoning_header { display:inline-flex; flex-wrap:nowrap; align-items:center; gap:0; padding:0 8px; background:linear-gradient(180deg,var(--nt-secondary),var(--nt-surface)); border:0; border-radius:6px; color:var(--nt-muted); font-size:var(--nt-ui); margin:0; height:28px; min-height:28px; align-self:center; }
#chat .mes_reasoning_header:hover,#chat .mes_reasoning_details[open] .mes_reasoning_header { background:linear-gradient(180deg,var(--nt-hover),var(--nt-secondary)); color:var(--nt-text); }
#chat .mes_reasoning_header:focus-visible { outline:2px solid var(--nt-accent); outline-offset:2px; }
#chat .mes_reasoning_arrow { display:none; }
#chat .mes_reasoning_header_title { display:flex; align-items:center; height:24px; padding:0; line-height:0; font-size:0; }
#chat .mes_reasoning_header_title::after { content:var(--nt-reasoning-label); display:block; font:400 var(--nt-ui)/24px var(--nt-serif); }
/* 推理操作组间距。 */
#chat .mes_reasoning_actions { margin:0 0 0 auto; align-items:center; gap:2px; flex-shrink:0; }
#chat :is(.mes_edit_buttons,.mes_reasoning_actions) .menu_button { background:transparent; color:var(--nt-text); border:0; box-shadow:none; filter:none; text-shadow:none; padding:6px; }
#chat :is(.mes_edit_buttons,.mes_reasoning_actions) .menu_button:hover { background:var(--nt-hover); }
#chat :is(.edit_textarea,.mes_reasoning_edit) { font-family:var(--nt-serif); }

#chat :is(.mes_text,.mes_reasoning) hr { height:1px; border:0; background:var(--nt-border); box-shadow:none; margin:24px 0; }
::selection { background:var(--nt-selection-bg); color:var(--nt-text); }

/* ---------- 特殊状态 ---------- */
/* 头像大图等比显示，并保留关闭入口。 */
.zoomed_avatar[id] { --nt-viewer-height:min(calc(100dvh - 32px),90dvh); width:fit-content; min-width:0; left:16px; bottom:16px; padding:0; border:0; overflow:hidden; filter:none; z-index:30001; max-width:calc(100dvw - 32px); max-height:var(--nt-viewer-height)!important; background:transparent; box-shadow:none; border-radius:6px; }
.zoomed_avatar[id] .zoomed_avatar_container { width:auto; background:transparent; max-width:min(640px,calc(100dvw - 32px)); max-height:var(--nt-viewer-height); }
.zoomed_avatar[id] img { display:block; width:auto; margin:auto; max-width:min(640px,calc(100dvw - 32px)); height:auto; max-height:var(--nt-viewer-height); object-fit:contain; }
.zoomed_avatar[id] .panelControlBar { position:absolute; inset:6px 6px auto 6px; background:transparent; min-height:0; justify-content:flex-end; pointer-events:auto; opacity:1; }
.zoomed_avatar[id] .dragClose { pointer-events:auto; color:#fff; background:#25251eb3; border-radius:6px; width:var(--nt-control); height:var(--nt-control); box-shadow:none; filter:none; display:flex; align-items:center; justify-content:center; opacity:1; }
.zoomed_avatar[id] .dragClose { --nt-glyph:"\e1b1"; }
.zoomed_avatar[id] { max-width:calc(100dvw - 32px)!important; }
.zoomed_avatar[id] .dragClose:hover { background:#25251ee6; }
.zoomed_avatar[id] .dragClose:active { background:#25251e; }
.zoomed_avatar[id] .drag-grabber { pointer-events:auto; }
/* 手机头像大图居中定位。 */
@media(max-width:1000px) {
 body:not(.waifuMode) .zoomed_avatar[id] { position:fixed; z-index:3010; left:50dvw!important; top:50dvh!important; right:auto!important; bottom:auto!important; transform:translate(-50%,-50%); width:fit-content; height:auto; min-width:0; min-height:0; padding:0; overflow:hidden; }
}
/* 面板锁定按钮。 */
:is(#lm_button_panel_pin_div,#rm_button_panel_pin_div,#WI_button_panel_pin_div) > label { display:inline-flex; flex:none; align-items:center; justify-content:center; width:var(--nt-control); height:var(--nt-control); padding:0; border-radius:4px; font-size:var(--nt-icon); }
:is(#lm_button_panel_pin_div,#rm_button_panel_pin_div,#WI_button_panel_pin_div) > label > :is(.checked,.unchecked) { width:100%; height:100%; padding:0; line-height:var(--nt-control); text-align:center; }
:is(#lm_button_panel_pin_div,#rm_button_panel_pin_div,#WI_button_panel_pin_div) > label:hover { background:var(--nt-hover); }
/* 用户设定绑定徽标。 */
#user_avatar_block .avatar-container { overflow:visible; }
#user_avatar_block .avatar_state { font-size:14px; line-height:1.5; }
#user_avatar_block .avatar_state.disabled { opacity:1; }
/* 内容标签配色。 */
.tag { opacity:1; filter:none; background-image:linear-gradient(color-mix(in srgb,var(--nt-surface) 85%,transparent),color-mix(in srgb,var(--nt-surface) 85%,transparent)); color:var(--nt-text); text-shadow:none; }
/* 标签文字颜色。 */
.tag,.tag :is(.tag_name,.tag_remove) { color:var(--nt-text)!important; }
/* 提示词标题、名称与标记。 */
#completion_prompt_manager .completion_prompt_manager_header { color:var(--nt-text); }
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt :is(.completion_prompt_manager_prompt_name,.prompt-manager-inspect-action,.fa-solid) { color:var(--nt-text); text-shadow:none; filter:none; }
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid { color:var(--nt-muted); }
/* 未启用预设的次级文字色。 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled :is(.completion_prompt_manager_prompt_name,.completion_prompt_manager_prompt_description,.prompt-manager-inspect-action) { color:var(--nt-preset-inactive-text)!important; }
#completion_prompt_manager #completion_prompt_manager_list .drag-handle { color:var(--nt-muted); opacity:1; }
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt { border-color:var(--nt-border); border-radius:6px; }
/* 消息编辑工具栏。 */
#chat .mes_edit_buttons { filter:none; }
#chat .menu_button:is(.mes_edit_done,.mes_edit_cancel) { background:transparent; color:var(--nt-text); border:0; box-shadow:none; filter:none; opacity:1; }
#chat .menu_button:is(.mes_edit_done,.mes_edit_cancel):hover { background:var(--nt-hover); }
#chat :is(.mes_edit_done,.mes_edit_cancel)::before { content:var(--nt-glyph); font-family:"Notion Lucide"!important; font-weight:400; font-size:var(--nt-icon); text-shadow:none; }

