/* ==================== 模块08：第三方扩展 ==================== */
/* ---------- 快捷工具栏 ---------- */
/* 工具栏布局、按钮尺寸和展开状态由扩展设置控制。 */
/* 快捷工具栏按钮的颜色、圆角与交互反馈。 */
#send_form #input_helper_toolbar .input-helper-btn { color:var(--nt-text); background:transparent; border:0; box-shadow:none; border-radius:4px; }
/* ---------- QR助手 ---------- */
/* 统一QR助手的火箭按钮与操作菜单。 */
#quick-reply-rocket-button,#quick-reply-rocket-button > i { color:var(--nt-text)!important; background:transparent; }
body.qra-enabled #qr-assistant[role=dialog] { background:var(--nt-surface)!important; color:var(--nt-text); border:1px solid var(--nt-border); box-shadow:var(--nt-float-shadow); max-width:calc(100vw - 16px); max-height:65dvh; overflow:auto; }
body.qra-enabled #qr-assistant[role=dialog] .action-item { background:transparent!important; color:var(--nt-text)!important; border:0!important; text-align:left!important; justify-content:flex-start!important; font:400 var(--nt-ui)/1.5 var(--nt-serif)!important; padding:6px 10px!important; }
body.qra-enabled #qr-assistant[role=dialog] .action-item > span { text-align:left; }
#qr--bar .qr--button { background:transparent; color:var(--nt-text); border:0; }
/* 快捷操作的悬停与按下状态。 */
#send_form #input_helper_toolbar .input-helper-btn:hover,#qr--bar .qr--button:hover,body.qra-enabled #qr-assistant[role=dialog] .action-item:hover { background:var(--nt-quick-hover)!important; filter:none; }
#send_form #input_helper_toolbar .input-helper-btn:active,#qr--bar .qr--button:active,body.qra-enabled #qr-assistant[role=dialog] .action-item:active { background:var(--nt-quick-active)!important; filter:none; box-shadow:none; }

/* ---------- 柏宝箱预设分组 ---------- */
/* 统一柏宝箱预设分组的工具、分组和卡片。 */
#completion_prompt_manager :is(.bai-bai-preset-prompt-actions,.bai-bai-preset-prompt-action-button,.bai-bai-preset-prompt-icon-button) { opacity:1!important; }
/* 柏宝箱预设分组工具按钮状态。 */
#completion_prompt_manager #completion_prompt_manager_list :is(.bai-bai-preset-prompt-action-button,.bai-bai-preset-prompt-icon-button,.bai-bai-preset-group-action-button,.bai-bai-preset-group-toggle,.bai-bai-preset-favorites-toggle):hover { background:var(--nt-hover)!important; }
#completion_prompt_manager #completion_prompt_manager_list :is(.bai-bai-preset-favorites,.bai-bai-preset-global-library,.bai-bai-preset-group) { background:var(--nt-surface); }
#completion_prompt_manager #completion_prompt_manager_list :is(.bai-bai-preset-group-header,.bai-bai-preset-favorites-header) { background:var(--nt-surface); }
#completion_prompt_manager #completion_prompt_manager_list :is(.bai-bai-preset-group-header,.bai-bai-preset-favorites-header):hover { background:var(--nt-hover); }
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt { background:var(--nt-secondary); border-color:var(--nt-border); }

/* ---------- 酒馆助手 ---------- */
/* 统一选中导航和分段选项。 */
#extensions_settings .TH-custom-tailwind [class~="bg-[color-mix(in_srgb,var(--SmartThemeQuoteColor)_80%,transparent)]"],
#extensions_settings .TH-radio-button--selected {
 background:color-mix(in srgb,var(--nt-selection) 15%,var(--nt-surface)); color:var(--nt-text);
 border-color:var(--nt-selection); box-shadow:inset 0 0 0 1px var(--nt-selection);
}
#extensions_settings .TH-custom-tailwind [class~="bg-[color-mix(in_srgb,var(--SmartThemeQuoteColor)_80%,transparent)]"]:hover,
#extensions_settings .TH-radio-button--selected:hover { background:color-mix(in srgb,var(--nt-selection) 22%,var(--nt-surface)); }
#extensions_settings .TH-radio-button:not(.TH-radio-button--selected):hover { background:var(--nt-hover); }
#extensions_settings .TH-custom-tailwind .border-x-2 > .cursor-pointer:not([class~="bg-[color-mix(in_srgb,var(--SmartThemeQuoteColor)_80%,transparent)]"]):hover { background:var(--nt-hover); color:var(--nt-text); }
/* ---------- 正在输入 ---------- */
/* 统一主题代理选择菜单。 */
body .ti-dd-trigger:hover,body .ti-dd-trigger.open,body .ti-dd-search:focus { border-color:var(--nt-selection); }
body .ti-dd-panel { background:var(--nt-surface); border-color:var(--nt-border); box-shadow:var(--nt-float-shadow); }
body .ti-dd-head { border-color:var(--nt-border); }
body .ti-dd-search { background:var(--nt-field-surface); border-color:var(--nt-border); }
body .ti-dd-search:focus { background:var(--nt-field-surface); border-color:var(--nt-selection); }
body .ti-dd-collapse-all { border-color:var(--nt-border); }
body :is(.ti-dd-collapse-all,.ti-dd-group-head,.ti-dd-item):hover { background:var(--nt-hover); border-color:var(--nt-border); }
body .ti-dd-group-head:focus-visible { background:var(--nt-hover); outline:2px solid var(--nt-selection); }
body .ti-dd-item.selected { background:var(--nt-secondary); outline:1px solid var(--nt-selection); outline-offset:-1px; }

/* ---------- Top Info Bar聊天信息栏 ---------- */
body {
/* 主菜单、聊天信息栏、连接配置行共用顶部安全距离。 */
#sheld:has(> #extensionTopBar) { --nt-info-height:48px; --nt-profile-height:40px; --nt-top-safe:calc(var(--topBarBlockSize) + var(--nt-info-height) + 8px); }
#sheld:has(> #extensionTopBar):has(> #extensionConnectionProfiles.visible) { --nt-top-safe:calc(var(--topBarBlockSize) + var(--nt-info-height) + var(--nt-profile-height) + 16px); }
#extensionTopBar,#extensionConnectionProfiles {
 position:fixed; left:50%; right:auto; transform:translateX(-50%); z-index:3004;
 box-sizing:border-box; width:min(760px,var(--nt-page-max),var(--sheldWidth),calc(100dvw - 16px)); max-width:calc(100dvw - 16px);
 margin:0; padding:7px; gap:2px; align-items:center; border:1px solid var(--nt-border); border-radius:8px;
 background:var(--nt-surface); color:var(--nt-text); box-shadow:var(--nt-float-shadow); backdrop-filter:none;
 font:400 var(--nt-ui)/1.4 var(--nt-serif);
}
#extensionTopBar { top:var(--topBarBlockSize); height:var(--nt-info-height); flex-wrap:nowrap; }
#extensionConnectionProfiles { top:calc(var(--topBarBlockSize) + var(--nt-info-height) + 8px); height:var(--nt-profile-height); flex-wrap:nowrap; padding:3px 7px; }
#extensionTopBar .right_menu_button { display:inline-flex; align-items:center; justify-content:center; flex:0 0 32px; width:32px; height:32px; padding:0; margin:0; border:0; border-radius:4px; font-size:16px; line-height:1; background:transparent; color:var(--nt-text); filter:none; text-shadow:none; }
#extensionTopBar .right_menu_button:hover { background:var(--nt-hover); filter:none; }
#extensionTopBar .right_menu_button.active { background:var(--nt-selection-bg); color:var(--nt-text); filter:none; }
#extensionTopBar .right_menu_button:focus-visible { outline:2px solid var(--nt-selection); outline-offset:0; }
#extensionTopBar .not-in-chat { color:var(--nt-muted); opacity:.6; }
#extensionTopBar #extensionTopBarChatName,#extensionTopBar #extensionTopBarSearchInput,#extensionConnectionProfiles #extensionConnectionProfilesSelect {
 box-sizing:border-box; flex:1 1 0; min-width:0; max-width:none; width:0; height:32px; min-height:32px;
 margin:0; padding:0 6px; color:var(--nt-text); background-color:var(--nt-field-surface); border:1px solid var(--nt-border); border-radius:4px;
 opacity:1; font:400 var(--nt-ui)/1.4 var(--nt-serif); text-overflow:ellipsis;
}
#extensionTopBar #extensionTopBarChatName,#extensionConnectionProfiles #extensionConnectionProfilesSelect { padding-right:24px; }
#extensionTopBar #extensionTopBarSearchInput::placeholder { color:var(--nt-muted); opacity:1; }
#extensionConnectionProfilesStatus { flex:1 1 0; min-width:0; opacity:1; font-size:var(--nt-note); }
#extensionConnectionProfiles .null-icon { display:none; }
#extensionConnectionProfiles img { max-width:20px; max-height:20px; }
/* 聊天列表侧栏：桌面宽度与聊天纸面分别配置。 */
#extensionSideBar {
 box-sizing:border-box; width:var(--nt-sidebar-width); min-width:0; max-width:calc(100dvw - 16px);
 top:var(--topBarBlockSize); bottom:auto; left:8px; height:calc(100dvh - var(--topBarBlockSize) - 8px); max-height:calc(100dvh - var(--topBarBlockSize) - 8px);
 padding:8px; border:1px solid var(--nt-border); border-radius:8px; background:var(--nt-surface); color:var(--nt-text);
 box-shadow:var(--nt-float-shadow); filter:none; backdrop-filter:none; z-index:3006; font:400 var(--nt-ui)/1.5 var(--nt-serif);
}
#extensionSideBar .panelControlBar { flex:none; height:32px; gap:2px; justify-content:flex-end; background:transparent; }
#extensionSideBar .drag-grabber { display:none; }
#extensionSideBar .dragClose { display:inline-flex; align-items:center; justify-content:center; width:32px; height:32px; margin:0; padding:0; font-size:16px; border:0; border-radius:4px; background:transparent; color:var(--nt-muted); }
#extensionSideBar .dragClose:hover { background:var(--nt-hover); color:var(--nt-text); }
#extensionSideBar .dragClose:focus-visible { outline:2px solid var(--nt-selection); outline-offset:0; }
#extensionSideBar #extensionSideBarContainer { min-height:0; width:100%; margin:36px 0 0; padding:0; gap:4px; overflow:auto; }
#extensionSideBar #extensionSideBarContainer .sideBarItem { padding:8px; border:1px solid var(--nt-border); border-radius:6px; gap:4px; filter:none; transition:background-color 120ms ease; }
#extensionSideBar #extensionSideBarContainer .sideBarItem:hover { background:var(--nt-hover); }
#extensionSideBar #extensionSideBarContainer .sideBarItem.selected { background:var(--nt-selection-bg); border-color:var(--nt-selection); }
#extensionSideBar .chatNameContainer,#extensionSideBar .chatMessageContainer { min-width:0; gap:6px; }
#extensionSideBar .chatName,#extensionSideBar .chatMessage { min-width:0; flex:1 1 auto; }
#extensionSideBar .chatDate,#extensionSideBar .chatStats { flex:none; color:var(--nt-muted); }
@media(max-width:1000px) {
 #extensionTopBar,#extensionConnectionProfiles { width:min(760px,var(--nt-page-max),var(--sheldWidth),calc(100dvw - 16px)); }
 /* 手机侧栏在视口内水平居中，宽度由侧栏配置和可用屏宽共同决定。 */
 #extensionSideBar { position:fixed; left:0!important; right:0!important; margin-inline:auto!important; top:var(--topBarBlockSize)!important; bottom:auto!important; width:min(var(--nt-sidebar-width),calc(100dvw - 16px))!important; min-width:0!important; max-width:calc(100dvw - 16px)!important; height:calc(100dvh - var(--topBarBlockSize) - 8px)!important; }
}
@media(max-width:600px) {
 #sheld:has(> #extensionTopBar) { --nt-info-height:84px; --nt-profile-height:64px; }
 #extensionTopBar { display:grid; grid-template-columns:repeat(14,minmax(0,1fr)); grid-template-rows:36px 32px; gap:2px; padding:6px 7px; }
 #extensionTopBar #extensionTopBarChatName { grid-row:1; grid-column:1 / 8; }
 #extensionTopBar #extensionTopBarSearchInput { grid-row:1; grid-column:8 / 15; }
 #extensionTopBar #extensionTopBarChatName,#extensionTopBar #extensionTopBarSearchInput { width:100%; height:36px; }
 #extensionTopBar .right_menu_button { grid-row:2; grid-column:span 2; justify-self:center; }
 #extensionConnectionProfiles.visible { display:grid; grid-template-columns:20px minmax(0,1fr) 20px; grid-template-rows:32px 20px; gap:2px; }
 #extensionConnectionProfiles #extensionConnectionProfilesSelect { width:100%; grid-column:2; grid-row:1; }
 #extensionConnectionProfilesStatus { grid-column:1 / -1; grid-row:2; text-align:left; }
}
@media(prefers-reduced-motion:reduce) { #extensionSideBar #extensionSideBarContainer .sideBarItem { transition:none; } }
}

/* ---------- 柏宝书 ---------- */
/* 顶栏入口使用书签书本线性图标。 */
#top-settings-holder #bbs-topbar-button .drawer-icon.fa-solid.fa-book-bookmark::before {
 content:var(--nt-glyph)!important; font-family:"Notion Lucide"!important; font-weight:400!important;
 font-size:var(--nt-icon)!important; line-height:1; color:inherit; text-shadow:none; filter:none;
}
#top-settings-holder #bbs-topbar-button { background:transparent; }
#top-settings-holder #bbs-topbar-button .drawer-icon { display:flex; align-items:center; justify-content:center; padding:0; }
#top-settings-holder #bbs-topbar-button .drawer-icon:hover { background:var(--nt-hover); color:var(--nt-text); }
#top-settings-holder #bbs-topbar-button .drawer-icon:focus-visible { outline:2px solid var(--nt-selection); outline-offset:0; }

/* ==================== 模块：砚台人设馆兼容层 ==================== */
/* 只在砚台人设馆接管原生入口时生效；不修改人设馆代码，也不影响其他主题页面。 */
#PersonaManagement:has(#yt-persona-native-workspace) > .flex-container:first-child {
  display:block !important;
  width:100% !important;
  min-width:0 !important;
  gap:var(--nt-group-gap) var(--nt-tool-gap) !important;
}
#PersonaManagement:has(#yt-persona-native-workspace) > .flex-container:first-child > .flex-container:first-child {
  display:grid !important;
  grid-template-columns:minmax(0,1fr) auto !important;
  align-items:center !important;
  width:100% !important;
  min-width:0 !important;
  flex-wrap:nowrap !important;
  gap:var(--nt-tool-gap) !important;
}
#PersonaManagement:has(#yt-persona-native-workspace) > .flex-container:first-child > .flex-container:first-child > .flex-container:first-child {
  display:flex !important;
  align-items:center !important;
  width:auto !important;
  min-width:0 !important;
  flex:1 1 auto !important;
}
#PersonaManagement:has(#yt-persona-native-workspace) > .flex-container:first-child > .flex-container:first-child > .flex-container:last-child {
  display:flex !important;
  align-items:center !important;
  justify-content:flex-end !important;
  flex-wrap:nowrap !important;
  width:auto !important;
  min-width:max-content !important;
  flex:0 0 auto !important;
  gap:var(--nt-tool-gap) !important;
}
#PersonaManagement:has(#yt-persona-native-workspace) > .flex-container:first-child > .flex-container:first-child > .flex-container:last-child > :is(.user_stats_button,#personas_backup,#personas_restore,#create_dummy_persona) {
  display:inline-flex !important;
  align-items:center !important;
  flex:0 0 auto !important;
  width:auto !important;
  min-width:max-content !important;
  height:var(--nt-control) !important;
  min-height:var(--nt-control) !important;
  margin:0 !important;
  white-space:nowrap !important;
  grid-column:auto !important;
  grid-row:auto !important;
}
/* 主题的通用 button 高度不能压扁人设馆编辑器头像。 */
#PersonaManagement:has(#yt-persona-native-workspace) .ytps-editor-avatar {
  display:grid !important;
  width:100% !important;
  height:auto !important;
  min-height:270px !important;
  align-self:stretch !important;
  overflow:hidden !important;
}
#PersonaManagement:has(#yt-persona-native-workspace) :is(.ytps-editor-avatar,.ytps-current-avatar,.ytps-row-avatar,.ytps-asset-thumb) > img {
  display:block !important;
  width:100% !important;
  height:100% !important;
  min-width:0 !important;
  min-height:0 !important;
  object-fit:cover !important;
}
@media(max-width:600px) {
  #PersonaManagement:has(#yt-persona-native-workspace) > .flex-container:first-child > .flex-container:first-child {
    grid-template-columns:minmax(0,1fr) !important;
    row-gap:var(--nt-tool-gap) !important;
  }
  #PersonaManagement:has(#yt-persona-native-workspace) > .flex-container:first-child > .flex-container:first-child > .flex-container:last-child {
    justify-content:flex-start !important;
    flex-wrap:wrap !important;
  }
  #PersonaManagement:has(#yt-persona-native-workspace) .ytps-editor-avatar {
    min-height:185px !important;
  }
}
